import{_ as e}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as s,d as a,o as n}from"./app-C3E8LLOD.js";const t="/foreverBlog/assets/3209332960e34ccfa0a04f19348eeca2-ByOazNQm.png",l="/foreverBlog/assets/cd1791cc336f42bd9fb94686020290f4-CCOOVAuv.png",r="/foreverBlog/assets/07611a220bf34c59b9b141679693a7b6-DzABtDog.png",d="/foreverBlog/assets/baee048d65914a3483577d130dd41530-CUAjwwNq.png",h="/foreverBlog/assets/566cbe0f6e7543268b18f8ee81e1c642-BOVg-tYT.png",g="/foreverBlog/assets/f8f332b99d5146dd943685470066a36e-BVGy9rNc.png",o="/foreverBlog/assets/d2d2c2b053ee404685739d226302aebd-Ca--yWtX.png",c="/foreverBlog/assets/13d2e94ea8f54083926aa18a9ba86567-CqvX8d7D.png",p={};function u(b,i){return n(),s("div",null,[...i[0]||(i[0]=[a('<h2 id="_0-引言" tabindex="-1"><a class="header-anchor" href="#_0-引言"><span>0 引言</span></a></h2><p>git是一个版本控制工具，它是一种分布式版本控制系统，主要用来管理项目中的代码，并且其是有Linux之父Linus Torvalds开发[1]。而本文由0及1，讲述git如何在windows上安装并与gitee实现连接。在此基础上，还讲述一些git的基本使用方法，并不定期更新在git中遇到的问题及解决办法。</p><h2 id="_1-git安装-windows" tabindex="-1"><a class="header-anchor" href="#_1-git安装-windows"><span>1 git安装（windows）</span></a></h2><p>点击下方链接，直接按照提示一直安装即可</p><p>下载地址：<a href="https://git-scm.com/downloads" target="_blank" rel="noopener noreferrer">https://git-scm.com/downloads</a></p><figure><img src="'+t+'" alt="在这里插入图片描述" tabindex="0" loading="lazy"><figcaption>在这里插入图片描述</figcaption></figure><h2 id="_2-git配置" tabindex="-1"><a class="header-anchor" href="#_2-git配置"><span>2 git配置</span></a></h2><h3 id="_2-1-gitee账号准备" tabindex="-1"><a class="header-anchor" href="#_2-1-gitee账号准备"><span>2.1 gitee账号准备</span></a></h3><ol><li><strong>账号注册</strong></li></ol><p>​ 点击下方的gitee链接，注册后并记住<strong>ID</strong>和<strong>邮箱</strong>，在后续git的连接需要用到</p><p>​ gitee官网：<a href="https://gitee.com" target="_blank" rel="noopener noreferrer">https://gitee.com</a></p><ol start="2"><li><p><strong>新建仓库</strong></p><p>点击首页右上方<strong>加号</strong>，选择新建仓库</p></li></ol><figure><img src="'+l+'" alt="在这里插入图片描述" tabindex="0" loading="lazy"><figcaption>在这里插入图片描述</figcaption></figure><p>​ 仅仅需要输入仓库名称再点击<strong>创建</strong>即可</p><figure><img src="'+r+`" alt="在这里插入图片描述" tabindex="0" loading="lazy"><figcaption>在这里插入图片描述</figcaption></figure><h3 id="_2-2-本地配置git" tabindex="-1"><a class="header-anchor" href="#_2-2-本地配置git"><span>2.2 本地配置git</span></a></h3><p>这一步主要是配置本地信息，才能通过git<strong>拉取</strong>和<strong>上传</strong>项目代码。可以理解告诉git我要将此项目上传到<code>gitee</code>还是其他代码托管平台，如：<code>github</code>。</p><ol><li><p><strong>全局配置</strong>[2]</p><p>通过全局配置，后续本地所有文件上传，都是上传到这个平台（<strong>新手建议设置全局</strong>）</p></li></ol><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git config --global user.name &quot;自己的github或gitte的用户名&quot;</span></span>
<span class="line"><span>git config --global user.email &quot;自己的github或gitte的绑定的主要邮箱&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>​ 这里的用户名和邮箱就是2.1第一点中注册时用到的信息，填写即可。</p><p>​ 填写完毕，输入以下命令查看相关配置是否成功</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git config list</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><figure><img src="`+d+`" alt="在这里插入图片描述" tabindex="0" loading="lazy"><figcaption>在这里插入图片描述</figcaption></figure><ol start="2"><li><p><strong>单个文件配置</strong>[2]</p><p>在涉及到某个项目的文件需要上传至与全局配置不同的代码托管平台时，则可以单独设置此文件夹下的上传路径</p></li></ol><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git config user.name &quot;&quot;</span></span>
<span class="line"><span>git config user.email &quot;&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-生成公钥并获取gitee的授权" tabindex="-1"><a class="header-anchor" href="#_2-3-生成公钥并获取gitee的授权"><span>2.3 生成公钥并获取gitee的授权</span></a></h3><p>可以理解成当你上传代码时，需要证明这个操作是”你“本人完成，而通过生成公钥，每次就不需要输入密码，通过这个已经配置好的公钥，服务器端就知道**”你是谁“**，并且这种方式能避免输入密码造成的泄露危险。</p><ol><li><p><strong>生成<code>ssh key</code></strong>[2]</p><ul><li>ssh-keygen -t rsa -C &quot;<a href="mailto:xxxxx@xxxxx.com" target="_blank" rel="noopener noreferrer">xxxxx@xxxxx.com</a>&quot;</li><li>注意：这里的 <code>xxxxx@xxxxx.com</code> 只是生成的 sshkey 的名称，并不约束或要求具体命名为某个邮箱</li><li>现网的大部分教程均讲解的使用邮箱生成，其一开始的初衷仅仅是为了便于辨识所以使用了邮箱。</li></ul></li><li><p><strong>获取 <code> public key</code></strong></p><ul><li>按照提示完成三次回车，即可生成 ssh key。通过查看 <code>~/.ssh/id_rsa.pub</code> 文件内容，获取到你的 public key</li><li>cat ~/.ssh/id_rsa.pub（也可以直接使用 <code>clip</code> 命令将文件内容复制到剪贴板中：clip &lt; ~/.ssh/id_rsa.pub）</li><li>复制生成后的 ssh key，通过仓库主页 <strong>「Settings」-&gt;「SSH and GPG keys」-&gt;「SSH keys」-&gt;「New SSH key」</strong> ，添加生成的 public key 添加到仓库中。</li><li>首次使用需要确认并添加主机到本机SSH可信列表。键入下方命令，提示<code>Are you sure you want to continue connecting (yes/no/[fingerprint])?</code>，键入yes完成认证 <ul><li>ssh -T <a href="mailto:git@github.com" target="_blank" rel="noopener noreferrer">git@github.com</a> （如果是绑定gitee，则输入：ssh -T <a href="mailto:git@gitee.com" target="_blank" rel="noopener noreferrer">git@gitee.com</a>）</li><li>若返回 <code>Hi XXX! You&#39;ve successfully authenticated, but Gitee.com does not provide shell access.</code>，则证明添加成功</li></ul></li></ul></li></ol><h3 id="_2-4-上传本地项目" tabindex="-1"><a class="header-anchor" href="#_2-4-上传本地项目"><span>2.4 上传本地项目</span></a></h3><p>通过上述的设置就已经将git基本配置好了，现在可以尝试将本地的任一项目上传至刚刚创建的仓库</p><ol><li><p><strong>进入项目根目录</strong></p><figure><img src="`+h+'" alt="在这里插入图片描述" tabindex="0" loading="lazy"><figcaption>在这里插入图片描述</figcaption></figure></li><li><p><strong>右键打开<code>git bash here</code></strong></p></li></ol><p>​ （1）初始化项目（第一次需要）</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git init</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>​ （2）上传此页面的所有文件</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git add .</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>​ （3）提交至待转区</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git commit -m &quot;上传测试&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>​ （4）添加要上传目的的仓库地址，在原来仓库可以找到仓库地址（第一次需要）</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git remote add origin &lt;remote-url&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>​ 查看当前仓库地址</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git remote -v</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>​ （5） 上传文件至服务器仓库</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git push origin master</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><figure><img src="'+g+'" alt="在这里插入图片描述" tabindex="0" loading="lazy"><figcaption>在这里插入图片描述</figcaption></figure><p>之后在gitee的仓库中就能看到上传的文件了</p><figure><img src="'+o+'" alt="在这里插入图片描述" tabindex="0" loading="lazy"><figcaption>在这里插入图片描述</figcaption></figure><h2 id="_3-git常用操作" tabindex="-1"><a class="header-anchor" href="#_3-git常用操作"><span>3 git常用操作</span></a></h2><h3 id="_3-1-初始化文件" tabindex="-1"><a class="header-anchor" href="#_3-1-初始化文件"><span>3.1 初始化文件</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git init</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-2-添加远程仓库" tabindex="-1"><a class="header-anchor" href="#_3-2-添加远程仓库"><span>3.2 添加远程仓库</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git remote add origin &lt;remote-url&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-3-添加全部文件至暂存区" tabindex="-1"><a class="header-anchor" href="#_3-3-添加全部文件至暂存区"><span>3.3 添加全部文件至暂存区</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git add .</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-4-提交文件至本地仓库" tabindex="-1"><a class="header-anchor" href="#_3-4-提交文件至本地仓库"><span>3.4 提交文件至本地仓库</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git commit -m &quot;&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-5-提交本地文件至远程仓库" tabindex="-1"><a class="header-anchor" href="#_3-5-提交本地文件至远程仓库"><span>3.5 提交本地文件至远程仓库</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git push origin master	##master 可修改其他分支</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-6-拉取远程仓库至本地" tabindex="-1"><a class="header-anchor" href="#_3-6-拉取远程仓库至本地"><span>3.6 拉取远程仓库至本地</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git pull origin master ##master 可修改其他分支</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-7-查看分支" tabindex="-1"><a class="header-anchor" href="#_3-7-查看分支"><span>3.7 查看分支</span></a></h3><p>查看本地分支</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git branch</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>查看远程和本地仓库全部信息</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git branch -a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>查看远程仓库分支信息</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git branch -r</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-8-拉取远程仓库所有分支信息" tabindex="-1"><a class="header-anchor" href="#_3-8-拉取远程仓库所有分支信息"><span>3.8 拉取远程仓库所有分支信息</span></a></h3><p>仅仅拉取远程仓库信息，不会修改本地分支内容</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git fetch</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-9-修改当前分支" tabindex="-1"><a class="header-anchor" href="#_3-9-修改当前分支"><span>3.9 修改当前分支</span></a></h3><p>切换本地其他分支（已存在）</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git chechkout tree_name</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git switch tree_name	## 新版本的命令，二者都可用</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>切换其他分支（若不存在，则本地强制创建）</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git checkout -b tree_name</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-10-查看暂存区状态" tabindex="-1"><a class="header-anchor" href="#_3-10-查看暂存区状态"><span>3.10 查看暂存区状态</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git status</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-11-配置信息" tabindex="-1"><a class="header-anchor" href="#_3-11-配置信息"><span>3.11 配置信息</span></a></h3><p>全局配置</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git config --global user.name &quot;&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git config --global user.email &quot;&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>局部配置</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git config user.name &quot;&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git config user.email &quot;&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="_4-未知问题及解决方案" tabindex="-1"><a class="header-anchor" href="#_4-未知问题及解决方案"><span>4 未知问题及解决方案</span></a></h2><p>这里将持续记录，并不间断更新我在工作中遇到的各种问题以及我对应的解决方案。因为git虽然是一个版本控制工具，但在实际项目中会遇到特别多的问题，并且当我们与其他一起合作时，“版本冲突”、“分支合并”、“版本回复”等等棘手的问题都是在工作中可能遇到的。而我将持续记录自己<strong>真实</strong>遇到的问题，并将自己的解决方案记录在此。</p><h3 id="_4-1-分支冲突" tabindex="-1"><a class="header-anchor" href="#_4-1-分支冲突"><span>4.1 分支冲突</span></a></h3><blockquote><p>问题阐述</p></blockquote><p>在本地修改了项目内容，并上传至gitee，此时从服务器中想拉取该分支的最新内容（服务器之前已拉取过该分支），但是系统提示分支冲突，不能直接拉取。系统显示的内容如下</p><figure><img src="'+c+`" alt="在这里插入图片描述" tabindex="0" loading="lazy"><figcaption>在这里插入图片描述</figcaption></figure><blockquote><p>问题解析</p></blockquote><p>提示的内容主要是要求我们针对本地项目与远程仓库项目不一致，需要你手动进行确认，而为什么会出现这样的情况？通常是因为 <strong>本地分支与远程分支的历史记录不一致</strong></p><p>假设远程仓库的分支有新的提交（例如别人推送了代码），而你的本地分支：</p><ol><li><strong>从未与远程分支关联过</strong>；</li><li><strong>本地有未提交的修改</strong>；</li><li><strong>之前拉取过但未正确合并</strong>。</li></ol><p>此时，Git 无法自动确定如何同步两者的差异，因此需要你手动指定解决方式。</p><blockquote><p><strong>解决方案</strong></p></blockquote><ol><li><strong>留远程，删本地</strong></li></ol><p>因为我的服务器不需要留存代码，只需要拉取最新的代码运行即可，所以只需要拉取远程分支，并强制拉取到本地即可</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git fetch --all</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git reset --hard origin/csdn_increase	## 强制重置本地分支</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="2"><li><strong>远程和本地文件都需要</strong></li></ol><p>对于需要远程和本地代码都需要留存的，可以按照下述方式进行操作</p><ul><li>提交代码至本地仓库</li></ul><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git add .</span></span>
<span class="line"><span>git commit -m &quot;提交代码至本地仓库&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>拉取远程仓库代码</li></ul><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git pull origin master	## 此时拉取的代码中远程和本地有冲突的地方，git的方案是将二者都保存下来</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>保留远程代码</li></ul><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git checkout --theirs file_name 	## 输入文件名，此时会保存远程文件</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>保留本地仓库代码</li></ul><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git checkout --ours file_name		## 输入文件名，此时会保存本地文件</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>保存修改</li></ul><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>git commit -m &quot;解决合并冲突：XXX使用远程版本，XXX使用本地版本&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="参考" tabindex="-1"><a class="header-anchor" href="#参考"><span>参考</span></a></h2><p>[1] <a href="https://zhuanlan.zhihu.com/p/615581394" target="_blank" rel="noopener noreferrer">(9 封私信 / 44 条消息) Git 使用教程：最详细、最正宗手把手教学（万字长文） - 知乎</a></p><p>[2] <a href="https://www.cnblogs.com/suhai/p/14449889.html" target="_blank" rel="noopener noreferrer">【Git】初始配置以及常用操作命令 - 中国制造 - 博客园</a></p>`,115)])])}const v=e(p,[["render",u]]),A=JSON.parse('{"path":"/%E5%B7%A5%E5%85%B7%E4%B8%8E%E6%A1%86%E6%9E%B6/git%E5%9F%BA%E7%A1%80%E9%85%8D%E7%BD%AE%E5%8F%8A%E5%B8%B8%E7%94%A8%E6%93%8D%E4%BD%9C/git%E5%9F%BA%E7%A1%80%E9%85%8D%E7%BD%AE%E5%8F%8A%E5%B8%B8%E7%94%A8%E6%93%8D%E4%BD%9C.html","title":"git基础配置及常用操作","lang":"zh-CN","frontmatter":{"title":"git基础配置及常用操作","date":"2025-09-11T18:52:01.000Z","categories":["工具与框架"],"tags":["git","环境配置"],"sticky":0,"description":"0 引言 git是一个版本控制工具，它是一种分布式版本控制系统，主要用来管理项目中的代码，并且其是有Linux之父Linus Torvalds开发[1]。而本文由0及1，讲述git如何在windows上安装并与gitee实现连接。在此基础上，还讲述一些git的基本使用方法，并不定期更新在git中遇到的问题及解决办法。 1 git安装（windows） ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"git基础配置及常用操作\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2025-09-11T18:52:01.000Z\\",\\"dateModified\\":null,\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"二进制星辰\\",\\"url\\":\\"https://blog.csdn.net/qq_63786218?type=blog\\"}]}"],["meta",{"property":"og:url","content":"https://mister-hope.github.io/foreverBlog/%E5%B7%A5%E5%85%B7%E4%B8%8E%E6%A1%86%E6%9E%B6/git%E5%9F%BA%E7%A1%80%E9%85%8D%E7%BD%AE%E5%8F%8A%E5%B8%B8%E7%94%A8%E6%93%8D%E4%BD%9C/git%E5%9F%BA%E7%A1%80%E9%85%8D%E7%BD%AE%E5%8F%8A%E5%B8%B8%E7%94%A8%E6%93%8D%E4%BD%9C.html"}],["meta",{"property":"og:site_name","content":"二进制星辰"}],["meta",{"property":"og:title","content":"git基础配置及常用操作"}],["meta",{"property":"og:description","content":"0 引言 git是一个版本控制工具，它是一种分布式版本控制系统，主要用来管理项目中的代码，并且其是有Linux之父Linus Torvalds开发[1]。而本文由0及1，讲述git如何在windows上安装并与gitee实现连接。在此基础上，还讲述一些git的基本使用方法，并不定期更新在git中遇到的问题及解决办法。 1 git安装（windows） ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:tag","content":"环境配置"}],["meta",{"property":"article:tag","content":"git"}],["meta",{"property":"article:published_time","content":"2025-09-11T18:52:01.000Z"}]]},"git":{},"readingTime":{"minutes":7.09,"words":2126},"filePathRelative":"工具与框架/git基础配置及常用操作/git基础配置及常用操作.md","excerpt":"<h2>0 引言</h2>\\n<p>git是一个版本控制工具，它是一种分布式版本控制系统，主要用来管理项目中的代码，并且其是有Linux之父Linus Torvalds开发[1]。而本文由0及1，讲述git如何在windows上安装并与gitee实现连接。在此基础上，还讲述一些git的基本使用方法，并不定期更新在git中遇到的问题及解决办法。</p>\\n<h2>1 git安装（windows）</h2>\\n<p>点击下方链接，直接按照提示一直安装即可</p>\\n<p>下载地址：<a href=\\"https://git-scm.com/downloads\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">https://git-scm.com/downloads</a></p>","autoDesc":true}');export{v as comp,A as data};
